head.script:
scwin.screenId = "jldinf90009";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = function () {
    let binds = [{ id: "txt_p8", fn: function(){ return ((String(($c.data.readValue("dma_pageContext", "zipList", { ctx: true, label: "zipList" })) == null ? '' : ($c.data.readValue("dma_pageContext", "zipList", { ctx: true, label: "zipList" }))).length === 0)); } }];
    $c.util.evalConds(binds);
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf90009.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_zipList_oncellclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_zipList_oncellclick = async function (rowIndex, columnIndex, columnId) { try { let dl = $c.util.getComponent('dlt_zipList'); let r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null; if (!r) { return; } scwin.setZipCode(r["zipCode"], r["address"], r["engAddress"]); return; } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: 'grd_zipList.oncellclick' }); } };


/**
 * @event
 * @name scwin.btn_sddSearchZip_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_sddSearchZip_onclick = function () {
    try {
        let kw = ($c.util.getComponent('ibx_sddSearchKeyword') || { getValue: function () { return ''; } }).getValue().trim();
        let o = {};
        ['searchType', 'searchWord', 'searchBldgNo', 'searchBldgNm'].forEach(function (fd) { try { let c = $c.util.getComponent(fd); if (c && c.getValue) { o[fd] = c.getValue(); } } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldinf90009' }); } });
        o.searchWord = kw;
        $c.win.setPageFrameSrc($c.win.getFrame(), '/jldinf90009/jldinf90009.xml', o);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90009.btn_sddSearchZip_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setZipCode
 * @author Inswave
 * @date 2026. 09. 06
 * @param zipCode address engAddress
 * @returns
 * @hidden N
*/
scwin.setZipCode = function (zipCode, address, engAddress) {
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function () { return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function () { return null; }, scwin: {} }).scwin || {})).setZipCode === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function () { return null; }, scwin: {} }).scwin || {})).setZipCode(zipCode, address, engAddress) : void 0), $c.win.closePopup([zipCode, address, engAddress]));
};
